WITH filtered AS (SELECT id, txn_type, amount, txn_time, merchant, is_flagged, ROUND(amount * 1.15, 2) AS amount_adjusted, CAST(is_flagged AS INT) AS is_flagged_flag FROM transactions WHERE NOT is_flagged) SELECT *, NTILE(5) OVER w_hist AS amount_adjusted_bucket, PERCENT_RANK() OVER (PARTITION BY merchant ORDER BY amount NULLS LAST) AS amount_percent_rank, LEAD(amount_adjusted, 1) OVER (ORDER BY amount_adjusted, id) AS next_amount_adjusted FROM filtered WINDOW w_hist AS (PARTITION BY txn_type, merchant ORDER BY amount_adjusted, id);
